CREATE TABLE kill_matrix(match_id VARCHAR, game_id VARCHAR, row_player_id INTEGER, col_player_id INTEGER, kills TINYINT, deaths TINYINT, op_kills TINYINT, op_deaths TINYINT, fk_kills TINYINT, fk_deaths TINYINT);;
CREATE TABLE maps(match_id VARCHAR, game_id VARCHAR, map_name VARCHAR, picked_by_team TINYINT, duration VARCHAR, score0 TINYINT, score1 TINYINT, performance_available BOOLEAN, economy_available BOOLEAN);;
CREATE TABLE matches(match_id VARCHAR, url VARCHAR, "event" VARCHAR, event_url VARCHAR, event_id INTEGER, event_slug VARCHAR, series_text VARCHAR, series_stage VARCHAR, series_round VARCHAR, date_text VARCHAR, ts_et VARCHAR, utc_timestamp TIMESTAMP, patch VARCHAR, team0_id INTEGER, team1_id INTEGER, score0 TINYINT, score1 TINYINT, status VARCHAR, listing_status VARCHAR, format VARCHAR, veto VARCHAR[], fetched_overview BOOLEAN, fetched_performance BOOLEAN, fetched_economy BOOLEAN, is_international BOOLEAN, region VARCHAR, is_showmatch BOOLEAN);;
CREATE TABLE notables(player_id INTEGER, match_id VARCHAR, game_id VARCHAR, player_team_idx TINYINT, stat_type VARCHAR, round_num TINYINT, opponents STRUCT("name" VARCHAR, agent VARCHAR)[]);;
CREATE TABLE players(player_id INTEGER, player_name VARCHAR, country VARCHAR, player_url VARCHAR);;
CREATE TABLE player_map(player_id INTEGER, match_id VARCHAR, game_id VARCHAR, team_idx TINYINT, agents VARCHAR[], rating_all DOUBLE, rating_atk DOUBLE, rating_def DOUBLE, acs_all SMALLINT, acs_atk SMALLINT, acs_def SMALLINT, adr_all SMALLINT, adr_atk SMALLINT, adr_def SMALLINT, kills_all TINYINT, kills_atk TINYINT, kills_def TINYINT, deaths_all TINYINT, deaths_atk TINYINT, deaths_def TINYINT, assists_all TINYINT, assists_atk TINYINT, assists_def TINYINT, fk_all TINYINT, fk_atk TINYINT, fk_def TINYINT, fd_all TINYINT, fd_atk TINYINT, fd_def TINYINT, kast_all TINYINT, kast_atk TINYINT, kast_def TINYINT, hs_pct_all TINYINT, hs_pct_atk TINYINT, hs_pct_def TINYINT, two_k TINYINT, three_k TINYINT, four_k TINYINT, five_k TINYINT, clutch_1v1 TINYINT, clutch_1v2 TINYINT, clutch_1v3 TINYINT, clutch_1v4 TINYINT, clutch_1v5 TINYINT, econ SMALLINT, plants TINYINT, defuses TINYINT);;
CREATE TABLE rounds(match_id VARCHAR, game_id VARCHAR, round_num TINYINT, winner_team TINYINT, side VARCHAR, outcome VARCHAR, loadout_t0 USMALLINT, loadout_t1 USMALLINT, bank_t0 USMALLINT, bank_t1 USMALLINT);;
CREATE TABLE teams(team_id INTEGER, team_name VARCHAR, team_url VARCHAR, country VARCHAR);;

